"""Check an actual oriented quad disk and its complete polygonal boundary.

Experimental building block for direct corner construction. It examines the
generated mesh, independently of any preliminary clearance-depth allocation.
It does not validate road profiles, the intended footprint, interpolation or
terrain. Those contracts still belong to the complete construction caller.
No existing constructor or acceptance gate is replaced by this module.
"""
import bpy

from .curved_corner_transition_ring_nodes import c, _disk_guard
from .path_surface_nodes import _Nodes
from .centerline_surface_nodes import _positive_quads
from . import blocked_boundary_nodes

NAME='Prochitecture Streets / Oriented quad disk guard v1'


def build():
    if NAME in bpy.data.node_groups:return bpy.data.node_groups[NAME]
    g=c.Graph(NAME)
    g.socket('Geometry','NodeSocketGeometry')
    for key in ('Valid','Topology Valid','Orientation Valid','Cells Valid','Boundary Valid'):
        g.socket(key,'NodeSocketBool','OUTPUT')
    g.socket('Boundary','NodeSocketGeometry','OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    mesh=inp.outputs['Geometry']
    native=_Nodes(g.g)
    index=g.node('GeometryNodeInputIndex').outputs[0]
    position=g.node('GeometryNodeInputPosition').outputs[0]
    topology=_disk_guard(g,mesh)
    # Corners of Edge enumerate its incident directed face-edge uses. Opposite
    # uses start at different endpoints; equal starts would add rather than
    # cancel that interior edge in the oriented face boundary.
    edge_uses=g.node('GeometryNodeInputMeshEdgeNeighbors').outputs['Face Count']
    starts=[]
    for slot in (0,1):
        corners=g.node('GeometryNodeCornersOfEdge','Incident face-edge use '+str(slot))
        g.bind(index,corners.inputs['Edge Index']);corners.inputs['Sort Index'].default_value=slot
        vertex=g.node('GeometryNodeVertexOfCorner')
        g.bind(corners.outputs['Corner Index'],vertex.inputs['Corner Index'])
        starts.append(vertex.outputs['Vertex Index'])
    opposite=1.-g.math('COMPARE',*starts)
    oriented=c._stat(g,mesh,c.choose(g,g.math('COMPARE',edge_uses,2.),opposite,True,'BOOLEAN'),domain='EDGE')
    face_corners=g.node('GeometryNodeCornersOfFace')
    g.bind(index,face_corners.inputs['Face Index'])
    all_quads=c._stat(g,mesh,g.math('COMPARE',face_corners.outputs['Total'],4.),domain='FACE')
    cells=all_quads*c.V(g,_positive_quads(native,mesh,index,position))

    border=g.node('GeometryNodeSeparateGeometry','Actual exposed edges of the generated surface')
    border.domain='EDGE'
    g.bind(mesh,border.inputs['Geometry'])
    g.bind(g.math('COMPARE',edge_uses,1.),border.inputs['Selection'])
    wire=border.outputs['Selection']
    neighbors=g.node('GeometryNodeInputMeshVertexNeighbors').outputs['Vertex Count']
    islands=g.node('GeometryNodeInputMeshIsland').outputs['Island Count']
    expected=c._count(g,wire)
    loop=(g.math('GREATER_THAN',expected,3.5)*
          c._stat(g,wire,g.math('COMPARE',neighbors,2.))*
          g.math('COMPARE',c._stat(g,wire,islands,'Max'),1.))
    curve=g.node('GeometryNodeMeshToCurve','Order the complete degree-two boundary')
    g.bind(wire,curve.inputs['Mesh'])
    points=g.node('GeometryNodeCurveToPoints','Retain every actual polygon vertex');points.mode='EVALUATED'
    g.bind(curve.outputs['Curve'],points.inputs['Curve'])
    vertices=g.node('GeometryNodePointsToVertices')
    g.bind(points.outputs['Points'],vertices.inputs['Points'])
    x,y,_=g.separate(position)
    ordered=g.setpos(vertices.outputs['Mesh'],g.xyz(x,y,0.));count=c._count(g,ordered)
    loop*=g.math('COMPARE',count,expected)
    # Nonneighbor contact alone omits consecutive collinear backtracking.
    # Require positively aligned directions when adjacent segments are collinear.
    at=c.V(g,index)
    p=c._vec(g,position)
    prev=c._vec(g,c._sample(g,ordered,position,g.math('MODULO',at+count-1.,count),'FLOAT_VECTOR'))
    nxt=c._vec(g,c._sample(g,ordered,position,g.math('MODULO',at+1.,count),'FLOAT_VECTOR'))
    a,b=c._sub(p,prev),c._sub(nxt,p)
    ua,ub=c._unit(g,a),c._unit(g,b)
    bent=g.math('GREATER_THAN',g.math('ABSOLUTE',c._cross(ua,ub)),1e-7)
    forward=g.math('GREATER_THAN',c._dot(ua,ub),0.)
    adjacent=c._stat(g,ordered,g.math('MAXIMUM',bent,forward))
    contacts=blocked_boundary_nodes.check(native,ordered.s,count.s,index,position,1e-6)
    boundary=loop*adjacent*c.V(g,contacts)
    valid=topology*oriented*cells*boundary
    for key,value in (('Valid',valid),('Topology Valid',topology),('Orientation Valid',oriented),
                      ('Cells Valid',cells),('Boundary Valid',boundary),('Boundary',ordered)):
        g.bind(value,out.inputs[key])
    return g.g
